import * as React from 'react'
import { motion } from 'motion/react'
import { Check, Pause, Play, RotateCcw, TriangleAlert } from 'lucide-react'
import { cn } from '@/lib/cn'
import { usePrefersReducedMotion } from '@/lib/use-reduced-motion'
import { useResolvedTheme, type ThemeMode } from '@/lib/use-resolved-theme'

export type CookLoadingState = 'loading' | 'done' | 'error'

export type CookLoadingProps = {
  /** Real progress, 0–100. Omit for indeterminate cooking; non-finite values are ignored. */
  progress?: number
  /** Host-owned state. When omitted, reaching 100% changes loading to done. */
  state?: CookLoadingState
  /** Loading caption and accessible progress name. */
  label?: string
  /** Optional supporting text; defaults to a message appropriate to the state. */
  description?: string
  /** Completed caption. */
  doneLabel?: string
  /** Failure caption. */
  errorLabel?: string
  /** Show the caption visually; accessible status is always present. */
  showLabel?: boolean
  /** Illustration width in px, clamped to 160–480 and the parent width. */
  size?: number
  /** Cooking speed multiplier, clamped to 0.5–2. */
  speed?: number
  /** CSS color for the illustration backdrop; default uses Framekit orange. */
  accent?: string
  /** Controlled animation pause; the task's progress continues independently. */
  paused?: boolean
  /** Initial animation pause in uncontrolled mode. */
  defaultPaused?: boolean
  /** Requested animation-pause changes. */
  onPausedChange?: (paused: boolean) => void
  /** Optional error recovery. The parent controls the resulting state. */
  onRetry?: () => void
  /** Text for the recovery button. */
  retryLabel?: string
  /** Follow the nearest class-based theme, or force one. */
  theme?: ThemeMode
  /** Root layout and spacing overrides. */
  className?: string
}

// Original eight-pose imagegen illustration. Embedded WebP keeps the registry item self-contained.
// Re-encode assets/cook-loading/chef-sprite.webp to update; see docs/COOK_LOADING.md.
const CHEF_SPRITE = 'data:image/webp;base64,'

// Alpha bounds in the 1774 × 887 source atlas, registered to a common counter baseline.
const FRAMES = [
  [48, 24, 348, 399], [492, 24, 347, 399], [934, 25, 347, 398], [1379, 25, 347, 398],
  [48, 468, 347, 398], [492, 468, 347, 398], [934, 468, 347, 398], [1379, 468, 347, 398],
] as const
const bounded = (value: number, fallback: number, min: number, max: number) => Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback

/**
 * An ink-and-ivory chef cooks over a warm circular backdrop while your application loads.
 * The original sprite, steam and progress are independent: pause freezes the art, never the task.
 * No simulated progress, network assets, timers that gate content, or global page side effects.
 */
export function CookLoading({
  progress, state: stateProp, label = 'Cooking things up…', description,
  doneLabel = 'Ready to serve.', errorLabel = 'Something needs another try.',
  showLabel = true, size = 280, speed = 1, accent, paused: pausedProp, defaultPaused = false,
  onPausedChange, onRetry, retryLabel = 'Try again', theme = 'auto', className,
}: CookLoadingProps) {
  const root = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const clock = React.useRef(0)
  const reduced = usePrefersReducedMotion()
  const resolved = useResolvedTheme(root, theme)
  const [innerPaused, setInnerPaused] = React.useState(defaultPaused)
  const paused = pausedProp ?? innerPaused
  const determinate = typeof progress === 'number' && Number.isFinite(progress)
  const pct = determinate ? bounded(progress!, 0, 0, 100) : undefined
  const state = stateProp ?? (pct === 100 ? 'done' : 'loading')
  const width = bounded(size, 280, 160, 480)
  const rate = bounded(speed, 1, 0.5, 2)
  const text = state === 'done' ? doneLabel : state === 'error' ? errorLabel : label
  const detail = description ?? (state === 'done' ? 'Everything is ready.' : state === 'error' ? 'We couldn’t finish loading.' : 'Good things take a moment.')
  const displayProgress = state === 'done' ? 100 : pct
  const progressId = React.useId()
  const liveText = `${text}${state === 'loading' && pct !== undefined ? ` ${Math.floor(pct / 10) * 10}% loaded.` : ''}`
  const [announcement, setAnnouncement] = React.useState('')

  React.useEffect(() => {
    // Coalesce rapid host updates and announce at 10% milestones, not every animation frame.
    const timer = window.setTimeout(() => setAnnouncement(liveText), 150)
    return () => window.clearTimeout(timer)
  }, [liveText])

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    let disposed = false, visible = false, raf = 0, last = 0, ready = false
    const image = new Image()
    const moving = !reduced && !paused && state === 'loading'
    const draw = () => {
      ctx.clearRect(0, 0, 320, 320)
      if (!ready) return
      const time = reduced || state !== 'loading' ? 0 : clock.current
      const frame = Math.floor(time * 8) % FRAMES.length
      const [sx, sy, sw, sh] = FRAMES[frame]
      // Stable baseline and scale prevent an animated sprite from shifting the page.
      ctx.drawImage(image, sx - 2, sy - 2, sw + 4, sh + 4, 34, 12, 252, 290)
      if (state !== 'loading') return
      // Three staggered wisps, emanating from the wok. The still frame omits the steam.
      if (!reduced) {
        ctx.lineWidth = 1.6; ctx.lineCap = 'round'
        for (let i = 0; i < 3; i++) {
          const phase = (time * 0.42 + i / 3) % 1
          const x = 166 + i * 11, y = 246 - phase * 52
          ctx.strokeStyle = resolved === 'dark' ? 'rgb(255 248 225 / 0.7)' : 'rgb(101 66 42 / 0.55)'
          ctx.globalAlpha = Math.sin(phase * Math.PI) * 0.65
          ctx.beginPath(); ctx.moveTo(x, y)
          ctx.bezierCurveTo(x - 9, y - 6, x + 8, y - 13, x, y - 22); ctx.stroke()
        }
        ctx.globalAlpha = 1
      }
    }
    const stop = () => { cancelAnimationFrame(raf); raf = 0; last = 0 }
    const loop = (now: number) => {
      raf = 0
      if (disposed || !visible || document.hidden || !moving || !ready) return
      if (last) clock.current += Math.min(0.05, (now - last) / 1000) * rate
      last = now; draw(); raf = requestAnimationFrame(loop)
    }
    const start = () => { if (!disposed && !raf && visible && !document.hidden && moving && ready) raf = requestAnimationFrame(loop) }
    const resize = () => {
      const w = canvas.getBoundingClientRect().width
      const dpr = Math.min(2, window.devicePixelRatio || 1)
      canvas.width = canvas.height = Math.max(1, Math.round(w * dpr))
      ctx.setTransform(canvas.width / 320, 0, 0, canvas.height / 320, 0, 0)
      draw(); start()
    }
    image.onload = () => { if (!disposed) { ready = true; resize() } }
    image.src = CHEF_SPRITE
    const observer = new ResizeObserver(resize); observer.observe(canvas)
    const intersection = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting
      if (visible) { draw(); start() } else stop()
    }); intersection.observe(canvas)
    const visibility = () => { if (document.hidden) stop(); else { draw(); start() } }
    document.addEventListener('visibilitychange', visibility)
    resize()
    return () => { disposed = true; stop(); image.onload = null; observer.disconnect(); intersection.disconnect(); document.removeEventListener('visibilitychange', visibility) }
  }, [paused, rate, reduced, resolved, state])

  const setPaused = () => {
    const next = !paused
    if (pausedProp === undefined) setInnerPaused(next)
    onPausedChange?.(next)
  }
  const buttonClass = 'inline-flex min-h-11 min-w-11 touch-manipulation items-center justify-center gap-2 rounded-full px-3 text-xs font-medium text-zinc-600 transition-colors hover:bg-black/[0.04] hover:text-zinc-950 active:bg-black/[0.08] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-signal-600 dark:text-zinc-300 dark:hover:bg-white/[0.06] dark:hover:text-white dark:active:bg-white/[0.1] dark:focus-visible:ring-signal-300'

  return (
    <div ref={root} data-state={state} className={cn(theme !== 'auto' && theme, 'inline-flex max-w-full flex-col items-center text-center', className)} style={{ width }}>
      <div className="relative aspect-square w-full shrink-0" aria-hidden="true">
        <div className="absolute inset-x-[10%] bottom-[9%] top-[8%] rounded-full bg-framekit-400 dark:bg-framekit-600" style={accent ? { backgroundColor: accent } : undefined} />
        <svg viewBox="0 0 320 320" className="absolute inset-0 size-full fill-none stroke-framekit-500/50 dark:stroke-framekit-400/50" style={accent ? { stroke: accent } : undefined}>
          <path d="M42 217 A132 132 0 0 1 77 58 M258 69 A132 132 0 0 1 280 107" strokeWidth="1" strokeLinecap="round" />
          <circle cx="269" cy="56" r="3" strokeWidth="2" />
        </svg>
        <canvas ref={canvasRef} className="relative block size-full" />
        {state !== 'loading' && <motion.span key={state} initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.7 }} animate={{ opacity: 1, scale: 1 }} transition={reduced ? { duration: 0.15 } : { type: 'spring', stiffness: 360, damping: 26 }} className={cn('absolute bottom-[6%] right-[10%] grid size-11 place-items-center rounded-full border-4 border-white shadow-sm dark:border-zinc-950', state === 'done' ? 'bg-emerald-700 text-white dark:bg-emerald-300 dark:text-emerald-950' : 'bg-amber-200 text-amber-950 dark:bg-amber-300')}>
          {state === 'done' ? <Check size={20} strokeWidth={2.5} /> : <TriangleAlert size={19} />}
        </motion.span>}
      </div>
      <div className={cn('w-full px-3', !showLabel && 'sr-only')}>
        <p className="text-balance break-words font-display text-2xl leading-tight tracking-tight text-zinc-950 dark:text-zinc-50">{text}</p>
        {detail && <p className="mt-2 text-pretty break-words text-sm leading-relaxed text-zinc-600 dark:text-zinc-400">{detail}</p>}
      </div>
      {state !== 'error' && <div id={progressId} role="progressbar" aria-label={text} aria-valuemin={0} aria-valuemax={100} aria-valuenow={displayProgress === undefined ? undefined : Math.round(displayProgress)} aria-valuetext={displayProgress === undefined ? 'Loading' : `${Math.round(displayProgress)}%`} className={cn('mt-5 w-full max-w-40 px-3', displayProgress === undefined && 'sr-only')}>
        <div aria-hidden="true" className="h-1 overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-800">
          {displayProgress !== undefined
            ? <motion.div className="h-full origin-left rounded-full bg-zinc-800 dark:bg-zinc-200" initial={false} animate={{ scaleX: displayProgress / 100 }} transition={reduced ? { duration: 0 } : { type: 'spring', stiffness: 180, damping: 28 }} />
            : <div className="h-full w-1/3 rounded-full bg-zinc-600 dark:bg-zinc-400" />}
        </div>
        {displayProgress !== undefined && showLabel && <p aria-hidden="true" className="mt-2 text-xs tabular-nums text-zinc-600 dark:text-zinc-400">{Math.round(displayProgress)}%</p>}
      </div>}
      <div className="mt-2 flex min-h-11 items-center justify-center">
        {state === 'loading' && !reduced && <button type="button" onClick={setPaused} aria-pressed={paused} className={buttonClass}>
          {paused ? <Play size={12} aria-hidden /> : <Pause size={12} aria-hidden />}{paused ? 'Resume animation' : 'Pause animation'}
        </button>}
        {state === 'error' && onRetry && <button type="button" onClick={onRetry} className={buttonClass}><RotateCcw size={14} aria-hidden />{retryLabel}</button>}
      </div>
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">{announcement}</span>
    </div>
  )
}
